css:
.prova-container {
	font-family: Arial, sans-serif;
	max-width: 800px;
	margin: 0 auto;
	padding: 20px;
}

.prova-header {
	text-align: center;
	border-bottom: 2px solid #333;
	padding-bottom: 15px;
	margin-bottom: 20px;
}

.prova-header h1 {
	margin: 0;
	font-size: 24px;
}

.prova-header .identificador {
	font-size: 14px;
	color: #666;
	margin-top: 5px;
}

.prova-info {
	display: flex;
	justify-content: space-between;
	margin-bottom: 20px;
	padding: 10px;
	background: #f5f5f5;
	border-radius: 5px;
}

.prova-info .info-item {
	text-align: center;
}

.prova-info .info-label {
	font-weight: bold;
	font-size: 12px;
	color: #666;
}

.prova-info .info-value {
	font-size: 14px;
}

.prova-instrucoes {
	border: 1px solid #ddd;
	padding: 15px;
	margin-bottom: 30px;
	background: #fafafa;
}

.prova-instrucoes h3 {
	margin-top: 0;
	border-bottom: 1px solid #ddd;
	padding-bottom: 10px;
}

.questao {
	margin-bottom: 30px;
	page-break-inside: avoid;
}

.questao-header {
	display: flex;
	align-items: center;
	margin-bottom: 10px;
}

.questao-numero {
	background: #333;
	color: white;
	width: 30px;
	height: 30px;
	border-radius: 50%;
	display: flex;
	align-items: center;
	justify-content: center;
	font-weight: bold;
	margin-right: 10px;
}

.questao-meta {
	font-size: 12px;
	color: #666;
}

.questao-meta span {
	margin-right: 15px;
}

.questao-enunciado {
	margin-bottom: 15px;
	line-height: 1.6;
}

.alternativas {
	margin-left: 20px;
}

.alternativa {
	margin-bottom: 10px;
	display: flex;
	align-items: flex-start;
}

.alternativa-letra {
	font-weight: bold;
	margin-right: 10px;
	min-width: 25px;
}

.espaco-resposta {
	border: 1px dashed #999;
	min-height: 100px;
	margin-top: 15px;
	padding: 10px;
}

.espaco-resposta-label {
	font-size: 12px;
	color: #666;
	margin-bottom: 5px;
}

.prova-footer {
	text-align: center;
	margin-top: 30px;
	padding-top: 15px;
	border-top: 1px solid #ddd;
	font-size: 12px;
	color: #666;
}

@media print {
	.questao {
		page-break-inside: avoid;
	}
}
